"""Merge the slices of one dataset, generated by several game instances, into the dataset a
single run would have written (M12-1, ``merge-slices``).

A slice is a complete dataset whose manifest has a ``slice`` member: its index among
``count`` slices, the world it generated in and its scene slots. The merge refuses, with a
:class:`MergeError` and without writing anything, unless the slices share one configuration
and slice count, every slice index appears once, the slots neither overlap nor leave a gap,
and every slice validates. It then links the images into place (copying across file
systems), so the slices stay untouched, writes the indexes ordered by scene index and
attempt, and writes the manifest a single run would record, without ``slice`` and with a
``worlds`` list naming each slice's world and slots, for replaying natural scenes in the
world that generated them. The merged dataset is validated before it appears.
"""

import contextlib
import hashlib
import json
import os
import shutil
from pathlib import Path
from typing import Any

from honey_factory_tools import dataset
from honey_factory_tools.schemas import Schemas

MANIFEST = "dataset.json"
SCENES = "scenes.jsonl"
SAMPLES = "samples.jsonl"

Record = dict[str, Any]


class MergeError(Exception):
    """The slices cannot be merged; nothing was written."""


def merge(slices: list[Path], output: Path, schemas: Schemas) -> Path:
    """Merge ``slices`` into ``<output>/<dataset id>/`` and return that directory."""
    manifests = [_manifest(path) for path in slices]
    order = _check(slices, manifests)
    for path in slices:
        errors = dataset.validate(path, schemas).errors
        if errors:
            raise MergeError(f"slice {path} does not validate: {errors[0]}")

    first = manifests[order[0]]
    target = output / first["dataset_id"]
    if target.exists():
        raise MergeError(f"{target} already exists")

    staging = output / f".{first['dataset_id']}.merging"
    if staging.exists():
        raise MergeError(f"{staging} is left from an earlier merge; remove it first")
    created_output = not output.exists()
    staging.mkdir(parents=True)
    try:
        scenes, samples = _indexes([slices[i] for i in order], staging)
        scene_bytes = "".join(line for _, line in scenes).encode()
        sample_bytes = "".join(samples).encode()
        (staging / SCENES).write_bytes(scene_bytes)
        (staging / SAMPLES).write_bytes(sample_bytes)
        merged = _merged_manifest([manifests[i] for i in order], scenes, scene_bytes, sample_bytes)
        (staging / MANIFEST).write_text(json.dumps(merged, indent=2) + "\n", encoding="utf-8")
        errors = dataset.validate(staging, schemas).errors
        if errors:
            raise MergeError(f"the merged dataset does not validate: {errors[0]}")
        staging.rename(target)
    except BaseException:
        # Only what this merge created goes: its staging folder, and the output folder if
        # the merge made it and it is still empty.
        shutil.rmtree(staging, ignore_errors=True)
        if created_output:
            with contextlib.suppress(OSError):
                output.rmdir()
        raise
    return target


def _manifest(path: Path) -> Record:
    try:
        manifest: Record = json.loads((path / MANIFEST).read_text(encoding="utf-8"))
    except (OSError, ValueError) as error:
        raise MergeError(f"{path}: cannot read {MANIFEST}: {error}") from error
    if "slice" not in manifest:
        raise MergeError(f"{path} is not a slice: its manifest has no slice member")
    if manifest["lifecycle"] != "complete":
        raise MergeError(f"{path} is {manifest['lifecycle']}, not complete")
    return manifest


def _check(slices: list[Path], manifests: list[Record]) -> list[int]:
    """The slices' order by slice index, once every check passes."""
    first = manifests[0]
    count: int = first["slice"]["count"]
    by_index: dict[int, int] = {}
    for position, manifest in enumerate(manifests):
        if (manifest["dataset_id"], manifest["resolved_config_sha256"]) != (
            first["dataset_id"],
            first["resolved_config_sha256"],
        ):
            raise MergeError(f"{slices[position]} has another configuration than {slices[0]}")
        part: Record = manifest["slice"]
        if part["count"] != count:
            raise MergeError(f"{slices[position]} is one of {part['count']} slices, not {count}")
        if part["index"] in by_index:
            raise MergeError(f"slice {part['index']} is given twice")
        by_index[part["index"]] = position
    missing = [index for index in range(count) if index not in by_index]
    if missing:
        raise MergeError(f"slice {missing[0]} of {count} is missing")

    seen: set[int] = set()
    for manifest in manifests:
        slots: list[int] = manifest["slice"]["slots"]
        overlap = seen.intersection(slots)
        if overlap:
            raise MergeError(f"scene slot {min(overlap)} is in two slices")
        seen.update(slots)
    requested: int = first["generator"]["accepted_scenes"]
    if seen != set(range(requested)):
        gap = min(set(range(requested)) - seen, default=None)
        raise MergeError(f"the slices miss scene slot {gap} of {requested}")
    return [by_index[index] for index in range(count)]


def _indexes(
    slices: list[Path], staging: Path
) -> tuple[list[tuple[tuple[int, int], str]], list[str]]:
    """Scene lines ordered by scene index and attempt, then each scene's sample lines in
    slice order, with every image linked into ``staging``."""
    scenes: list[tuple[tuple[int, int], str]] = []
    samples_by_scene: dict[str, list[str]] = {}
    for path in slices:
        for line in (path / SCENES).read_text(encoding="utf-8").splitlines(keepends=True):
            generation: Record = json.loads(line)["generation"]
            scenes.append(((generation["scene_index"], generation["attempt_index"]), line))
        for line in (path / SAMPLES).read_text(encoding="utf-8").splitlines(keepends=True):
            sample: Record = json.loads(line)
            samples_by_scene.setdefault(sample["scene_id"], []).append(line)
            for file in sample["files"].values():
                _link(path / file["path"], staging / file["path"])
    scenes.sort(key=lambda entry: entry[0])
    samples: list[str] = []
    for _, line in scenes:
        samples.extend(samples_by_scene.get(json.loads(line)["scene_id"], []))
    return scenes, samples


def _link(source: Path, destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    try:
        os.link(source, destination)
    except OSError:
        shutil.copy2(source, destination)


def _merged_manifest(
    manifests: list[Record],
    scenes: list[tuple[tuple[int, int], str]],
    scene_bytes: bytes,
    sample_bytes: bytes,
) -> Record:
    merged: Record = json.loads(json.dumps(manifests[0]))
    del merged["slice"]
    merged["created_at_utc"] = min(manifest["created_at_utc"] for manifest in manifests)
    merged["completed_at_utc"] = max(manifest["completed_at_utc"] for manifest in manifests)

    counts: Record = {key: 0 for key in manifests[0]["counts"] if key != "rejection_reasons"}
    reasons: dict[str, int] = {}
    for manifest in manifests:
        for key in counts:
            counts[key] += manifest["counts"][key]
        for reason, number in manifest["counts"]["rejection_reasons"].items():
            reasons[reason] = reasons.get(reason, 0) + number
    counts["requested_scenes"] = merged["generator"]["accepted_scenes"]
    counts["rejection_reasons"] = dict(sorted(reasons.items()))
    merged["counts"] = counts

    split_counts: Record = {}
    for split in manifests[0]["splits"]["counts"]:
        split_counts[split] = {
            key: sum(manifest["splits"]["counts"][split][key] for manifest in manifests)
            for key in ("scenes", "samples")
        }
    merged["splits"]["counts"] = split_counts
    if len(scenes) != counts["accepted_scenes"]:
        raise MergeError(
            f"the slices hold {len(scenes)} scenes but count {counts['accepted_scenes']}"
        )

    merged["integrity"]["indexes"] = {
        "scenes": {"bytes": len(scene_bytes), "sha256": hashlib.sha256(scene_bytes).hexdigest()},
        "samples": {"bytes": len(sample_bytes), "sha256": hashlib.sha256(sample_bytes).hexdigest()},
    }
    merged["worlds"] = [
        {"world": manifest["slice"]["world"], "slots": manifest["slice"]["slots"]}
        for manifest in manifests
    ]
    return merged
